import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

function validationRejection(error: unknown): ToolResponse {
  const details = error as
    | {
        keyword?: string;
        params?: {missingProperty?: unknown; type?: unknown};
        instancePath?: string;
        dataPath?: string;
        message?: string;
      }
    | undefined;
  if (details?.keyword === 'required' && typeof details.params?.missingProperty === 'string') {
    const parentPath = (details.instancePath || details.dataPath || '').replace(/^\//, '').replace(/\//g, '.');
    const propertyPath = [parentPath, details.params.missingProperty].filter(Boolean).join('.');
    return {result: `Input validation failed: ${propertyPath} is required`};
  }
  const rawPath = details?.instancePath || details?.dataPath || '';
  const path = rawPath.replace(/^\//, '').replace(/\//g, '.') || 'input';
  if (details?.keyword === 'type' && typeof details.params?.type === 'string') {
    return {result: `Input validation failed at ${path}: expected ${details.params.type}`};
  }
  return {result: `Input validation failed at ${path}: ${details?.message ?? 'invalid input'}`};
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

const ajvOptions = {strict: false, validateFormats: false};
const ajv = new Ajv(ajvOptions as ConstructorParameters<typeof Ajv>[0]);

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validators = new WeakMap<object, ValidateFunction>();

  private compileSchema(schema: ToolDefinition['inputSchema']): ValidateFunction {
    const cached = this.validators.get(schema);
    if (cached) return cached;
    const validate = ajv.compile(schema);
    this.validators.set(schema, validate);
    return validate;
  }

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validate: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validate = this.compileSchema(resolved.inputSchema);
      } catch (error) {
        const message = error instanceof Error ? error.message : 'invalid input schema';
        throw new Error(`Invalid input schema for tool ${resolved.name}: ${message}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Returns schema rejections as tool results and throws only for unknown names; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = tool.validate ?? this.compileSchema(definition.inputSchema);
    if (!validate(input)) {
      return validationRejection(validate.errors?.[0]);
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {jest} from '@jest/globals';
import Ajv from 'ajv';
import {ToolRegistry, type ToolExecutor} from './registry.js';

const callCount = (executor: {mock: {calls: unknown[]}}): number => {
  const calls = executor.mock.calls;
  return calls.length;
};

const registerWeatherTool = (registry: ToolRegistry, executor: ToolExecutor): void => {
  registry.register(
    {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    executor
  );
};

describe('ToolRegistry', () => {
  it('returns a required-property rejection without invoking the executor', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'sunny');
    registerWeatherTool(registry, executor);

    const response = await registry.execute('get_weather', {});

    expect({
      resultNamesRequiredLocation: /location.*required|required.*location/i.test(response.result),
      executorCalls: callCount(executor),
    }).toEqual({resultNamesRequiredLocation: true, executorCalls: 0});
  });

  it('includes the nested property path for a missing required value', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'ok');
    registry.register(
      {
        name: 'nested_tool',
        description: 'Read a nested value',
        inputSchema: {
          type: 'object',
          properties: {
            profile: {
              type: 'object',
              properties: {location: {type: 'string'}},
              required: ['location'],
            },
          },
        },
      },
      executor
    );

    const response = await registry.execute('nested_tool', {profile: {}});

    expect({
      resultNamesRequiredNestedLocation: /profile\.location.*required|required.*profile\.location/i.test(
        response.result
      ),
      executorCalls: callCount(executor),
    }).toEqual({resultNamesRequiredNestedLocation: true, executorCalls: 0});
  });

  it('compiles a function-valued schema once when the same schema object is reused', async () => {
    const inputSchema = {type: 'object', properties: {}};
    const registry = new ToolRegistry();
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    registry.register(
      () => ({name: 'dynamic_tool', description: 'Dynamic schema', inputSchema}),
      async () => 'ok'
    );

    await registry.execute('dynamic_tool', {});
    await registry.execute('dynamic_tool', {});

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });

  it('passes valid input with extra properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Paris', unit: 'celsius'};
    const executor = jest.fn(async (_input: Record<string, unknown>) => 'sunny');
    registerWeatherTool(registry, executor);

    await registry.execute('get_weather', input);

    expect({calls: executor.mock.calls.length, input: executor.mock.calls[0]?.[0]}).toEqual({
      calls: 1,
      input,
    });
  });

  it('rejects a wrong type with the field path and expected type without exposing the value', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'sunny');
    registerWeatherTool(registry, executor);

    const response = await registry.execute('get_weather', {location: 8675309});

    expect({
      result: response.result,
      executorCalls: callCount(executor),
    }).toEqual({result: 'Input validation failed at location: expected string', executorCalls: 0});
  });

  it('reports root property paths without a leading dot', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'ok');
    registerWeatherTool(registry, executor);

    const response = await registry.execute('get_weather', {location: 8675309});

    expect({result: response.result, calls: callCount(executor)}).toEqual({
      result: 'Input validation failed at location: expected string',
      calls: 0,
    });
  });
});
